<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
  :root {
    --bg: #f1f3f7;
    --col-bg: #e9ecf2;
    --card-bg: #ffffff;
    --ink: #1f2430;
    --muted: #6b7280;
    --accent: #4f6df5;
    --radius: 12px;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    background: var(--bg);
    color: var(--ink);
    font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
    padding: 32px 24px;
  }
  h1 {
    margin: 0 0 20px;
    font-size: 1.5rem;
    letter-spacing: -0.01em;
  }
  .toolbar {
    display: flex;
    gap: 10px;
    margin-bottom: 24px;
    max-width: 480px;
  }
  #new-card {
    flex: 1;
    padding: 10px 14px;
    font-size: 0.95rem;
    border: 1px solid #d3d8e2;
    border-radius: 10px;
    background: #fff;
    outline: none;
    transition: border-color .15s, box-shadow .15s;
  }
  #new-card:focus {
    border-color: var(--accent);
    box-shadow: 0 0 0 3px rgba(79,109,245,.15);
  }
  #add-card {
    padding: 10px 18px;
    font-size: 0.95rem;
    font-weight: 600;
    color: #fff;
    background: var(--accent);
    border: none;
    border-radius: 10px;
    cursor: pointer;
    transition: background .15s, transform .1s;
  }
  #add-card:hover { background: #3d5ae8; }
  #add-card:active { transform: scale(.97); }

  .board {
    display: grid;
    grid-template-columns: repeat(3, minmax(220px, 1fr));
    gap: 18px;
    align-items: start;
    max-width: 1100px;
  }
  .column {
    background: var(--col-bg);
    border-radius: var(--radius);
    padding: 14px;
    min-height: 260px;
    display: flex;
    flex-direction: column;
    transition: background .15s, outline-color .15s;
    outline: 2px dashed transparent;
    outline-offset: -2px;
  }
  .column.drag-over {
    background: #dde4f5;
    outline-color: var(--accent);
  }
  .col-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
    padding: 0 4px;
  }
  .col-title {
    font-size: 0.85rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--muted);
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .dot { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }
  #col-todo .dot  { background: #f59e0b; }
  #col-doing .dot { background: #4f6df5; }
  #col-done .dot  { background: #10b981; }
  .count {
    background: #fff;
    color: var(--muted);
    font-size: 0.75rem;
    font-weight: 700;
    min-width: 24px;
    text-align: center;
    padding: 3px 8px;
    border-radius: 999px;
    box-shadow: 0 1px 2px rgba(0,0,0,.06);
  }
  .cards {
    display: flex;
    flex-direction: column;
    gap: 10px;
    flex: 1;
    min-height: 60px;
  }
  .card {
    background: var(--card-bg);
    border-radius: 10px;
    padding: 12px 14px;
    box-shadow: 0 1px 3px rgba(20,24,40,.08), 0 1px 2px rgba(20,24,40,.05);
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 10px;
    cursor: grab;
    font-size: 0.95rem;
    line-height: 1.4;
    transition: box-shadow .15s, transform .1s, opacity .15s;
  }
  .card:hover {
    box-shadow: 0 4px 12px rgba(20,24,40,.12), 0 2px 4px rgba(20,24,40,.06);
    transform: translateY(-1px);
  }
  .card.dragging { opacity: .45; cursor: grabbing; }
  .card-title { word-break: break-word; }
  .card-del {
    flex: none;
    border: none;
    background: transparent;
    color: #b6bcc9;
    font-size: 1rem;
    line-height: 1;
    padding: 2px 4px;
    border-radius: 6px;
    cursor: pointer;
    transition: color .15s, background .15s;
  }
  .card-del:hover { color: #e11d48; background: #fdeef2; }
  .empty-hint {
    color: #a5abb8;
    font-size: 0.85rem;
    text-align: center;
    padding: 14px 0;
    border: 1.5px dashed #cfd5e1;
    border-radius: 10px;
  }
</style>
</head>
<body>
  <h1>Kanban Board</h1>

  <div class="toolbar">
    <input id="new-card" type="text" placeholder="New card title…" autocomplete="off">
    <button id="add-card">Add</button>
  </div>

  <div class="board">
    <section class="column" id="col-todo" data-col="todo">
      <header class="col-header">
        <span class="col-title"><span class="dot"></span>To Do</span>
        <span class="count">0</span>
      </header>
      <div class="cards"></div>
    </section>

    <section class="column" id="col-doing" data-col="doing">
      <header class="col-header">
        <span class="col-title"><span class="dot"></span>Doing</span>
        <span class="count">0</span>
      </header>
      <div class="cards"></div>
    </section>

    <section class="column" id="col-done" data-col="done">
      <header class="col-header">
        <span class="col-title"><span class="dot"></span>Done</span>
        <span class="count">0</span>
      </header>
      <div class="cards"></div>
    </section>
  </div>

<script>
(function () {
  "use strict";

  var STORAGE_KEY = "kanban-board-state-v1";
  var COLUMNS = ["todo", "doing", "done"];

  var input = document.getElementById("new-card");
  var addBtn = document.getElementById("add-card");

  function colEl(col) {
    return document.getElementById("col-" + col);
  }
  function cardsEl(col) {
    return colEl(col).querySelector(".cards");
  }

  // ---- State ----
  // state: { cards: [ { id, title, col } ] }  (order preserved per column)
  var state = load();

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        var parsed = JSON.parse(raw);
        if (parsed && Array.isArray(parsed.cards)) {
          parsed.cards = parsed.cards.filter(function (c) {
            return c && typeof c.title === "string" && COLUMNS.indexOf(c.col) !== -1;
          });
          return parsed;
        }
      }
    } catch (e) { /* corrupted state — start fresh */ }
    return { cards: [] };
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (e) { /* storage unavailable — board still works in-memory */ }
  }

  function uid() {
    return "c" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  // ---- Rendering ----
  function render() {
    COLUMNS.forEach(function (col) {
      var container = cardsEl(col);
      container.innerHTML = "";
      var cards = state.cards.filter(function (c) { return c.col === col; });

      cards.forEach(function (c) {
        container.appendChild(buildCard(c));
      });

      if (cards.length === 0) {
        var hint = document.createElement("div");
        hint.className = "empty-hint";
        hint.textContent = "Drop cards here";
        container.appendChild(hint);
      }

      colEl(col).querySelector(".count").textContent = cards.length;
    });
  }

  function buildCard(cardData) {
    var el = document.createElement("div");
    el.className = "card";
    el.draggable = true;
    el.dataset.id = cardData.id;

    var title = document.createElement("span");
    title.className = "card-title";
    title.textContent = cardData.title;

    var del = document.createElement("button");
    del.className = "card-del";
    del.type = "button";
    del.setAttribute("aria-label", "Delete card");
    del.textContent = "✕";
    del.addEventListener("click", function () {
      state.cards = state.cards.filter(function (c) { return c.id !== cardData.id; });
      save();
      render();
    });

    el.addEventListener("dragstart", function (ev) {
      ev.dataTransfer.setData("text/plain", cardData.id);
      ev.dataTransfer.effectAllowed = "move";
      el.classList.add("dragging");
    });
    el.addEventListener("dragend", function () {
      el.classList.remove("dragging");
    });

    el.appendChild(title);
    el.appendChild(del);
    return el;
  }

  // ---- Adding cards ----
  function addCard() {
    var title = input.value.trim();
    if (!title) return;
    state.cards.push({ id: uid(), title: title, col: "todo" });
    input.value = "";
    save();
    render();
    input.focus();
  }

  addBtn.addEventListener("click", addCard);
  input.addEventListener("keydown", function (ev) {
    if (ev.key === "Enter") addCard();
  });

  // ---- Drag & drop on columns ----
  COLUMNS.forEach(function (col) {
    var column = colEl(col);

    column.addEventListener("dragover", function (ev) {
      ev.preventDefault();
      ev.dataTransfer.dropEffect = "move";
      column.classList.add("drag-over");
    });

    column.addEventListener("dragleave", function (ev) {
      if (!column.contains(ev.relatedTarget)) {
        column.classList.remove("drag-over");
      }
    });

    column.addEventListener("drop", function (ev) {
      ev.preventDefault();
      column.classList.remove("drag-over");
      var id = ev.dataTransfer.getData("text/plain");
      var card = state.cards.find(function (c) { return c.id === id; });
      if (!card) return;
      // Move to end of the target column, preserving relative order of others.
      state.cards = state.cards.filter(function (c) { return c.id !== id; });
      card.col = col;
      state.cards.push(card);
      save();
      render();
    });
  });

  render();
})();
</script>
</body>
</html>
